// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";
import { parseToolResult } from "../src/util.js";
import type { ToolCallResult } from "../src/types.js";

test("prefers structuredContent over the content text block", () => {
  const result = parseToolResult<{ a: number }>({
    structuredContent: { a: 1 },
    content: [{ type: "text", text: JSON.stringify({ a: 2 }) }],
  });
  assert.deepStrictEqual(result, { a: 1 });
});

test("parses JSON from content[0].text when structuredContent is absent", () => {
  const result = parseToolResult<{ a: number }>({
    content: [{ type: "text", text: JSON.stringify({ a: 2 }) }],
  });
  assert.deepStrictEqual(result, { a: 2 });
});

test("falls back to the raw text when the text block is not JSON", () => {
  const result = parseToolResult<string>({ content: [{ type: "text", text: "hello" }] });
  assert.strictEqual(result, "hello");
});

test("throws using the first content block's text when isError is true", () => {
  assert.throws(
    () => parseToolResult({ isError: true, content: [{ type: "text", text: "boom" }] }),
    /boom/
  );
});

test("throws a generic message when isError is true but no content text exists", () => {
  assert.throws(() => parseToolResult({ isError: true }), /tool error/);
});

test("returns the raw result unchanged when there is no content array at all", () => {
  const raw: ToolCallResult = { content: undefined };
  const result = parseToolResult<ToolCallResult>(raw);
  assert.deepStrictEqual(result, raw);
});
